import UIKit

@available(iOS 27.0, *)
final class GlassCardViewController: UIViewController {
    override func viewDidLoad() {
        super.viewDidLoad()

        let glassView = UIVisualEffectView(effect: UIGlassEffect())
        glassView.translatesAutoresizingMaskIntoConstraints = false

        let titleLabel = UILabel()
        titleLabel.text = "Heute lernen"
        titleLabel.font = .preferredFont(forTextStyle: .title2)
        titleLabel.adjustsFontForContentSizeCategory = true
        titleLabel.translatesAutoresizingMaskIntoConstraints = false

        glassView.contentView.addSubview(titleLabel)
        view.addSubview(glassView)

        NSLayoutConstraint.activate([
            glassView.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            glassView.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            glassView.widthAnchor.constraint(lessThanOrEqualTo: view.widthAnchor, constant: -32),
            titleLabel.leadingAnchor.constraint(equalTo: glassView.contentView.leadingAnchor, constant: 24),
            titleLabel.trailingAnchor.constraint(equalTo: glassView.contentView.trailingAnchor, constant: -24),
            titleLabel.topAnchor.constraint(equalTo: glassView.contentView.topAnchor, constant: 18),
            titleLabel.bottomAnchor.constraint(equalTo: glassView.contentView.bottomAnchor, constant: -18)
        ])
    }
}

