import UIKit

enum Section { case main }

let registration = UICollectionView.CellRegistration<UICollectionViewListCell, String> { cell, _, title in
    var content = cell.defaultContentConfiguration()
    content.text = title
    cell.contentConfiguration = content
}

let dataSource = UICollectionViewDiffableDataSource<Section, String>(collectionView: collectionView) { collectionView, indexPath, item in
    collectionView.dequeueConfiguredReusableCell(using: registration, for: indexPath, item: item)
}

var snapshot = NSDiffableDataSourceSnapshot<Section, String>()
snapshot.appendSections([.main])
snapshot.appendItems(["SwiftUI", "UIKit", "AppKit"])
dataSource.apply(snapshot, animatingDifferences: true)
